[
  {
    "severity": "P1明显",
    "category": "contrast",
    "description": "底部备案/备注文字（“企业账号登录 · 提交与审批...”）与背景对比度严重不足，色值过于接近，在低亮度屏幕下几乎不可见。",
    "suggestion": "将文字颜色提升至更高亮度的琥珀色或浅酱色（如 #8C7A6D），确保符合 WCAG AA 级对比度标准。"
  },
  {
    "severity": "P1明显",
    "category": "contrast",
    "description": "输入框占位符文字（“业务账号 (如 buyer)”）与卡片深褐背景对比度不足，视觉识别效率低。",
    "suggestion": "调亮占位符颜色，建议使用浅琥珀灰或暖灰色，提升暗色模式下的可读性。"
  },
  {
    "severity": "P2瑕疵",
    "category": "ua-default-style",
    "description": "输入框下边框（边框线）表现为 1px 的扁平直角细线，呈现 Web 端 Input 标签的默认观感，缺乏移动端组件的精致感。",
    "suggestion": "建议根据「酱园琥珀」语言，将输入区改为浅酱色底色的微圆角（4-8px）色块，或加粗底线并赋予微弱的琥珀渐变/圆角端点。"
  },
  {
    "severity": "P2瑕疵",
    "category": "inconsistency",
    "description": "组件形态不统一：输入框使用底边框风格（线型），而登录按钮使用全圆角药丸风格（面型），两者设计语言冲突。",
    "suggestion": "建议统一形态，将输入框改为带微圆角的框式设计，或将按钮圆角调整为与输入框比例一致的圆角矩形。"
  },
  {
    "severity": "P2瑕疵",
    "category": "typography",
    "description": "副标题“食品企业移动端 · 单据与问答”的字重过细且行间距与上方主标题过于紧凑，导致文字节奏略显局促。",
    "suggestion": "适当增加主副标题间的间距（由目前的约 12px 增至 16px-20px），并微调副标题透明度以增强层级感。"
  },
  {
    "severity": "P2瑕疵",
    "category": "spacing",
    "description": "登录卡片内部边距（Padding）上下失衡：底部按钮到卡片底边的距离与上方标题到顶边的距离不一致，视觉重心略微靠下。",
    "suggestion": "增加卡片底部的内边距（Padding-bottom），使卡片内上下留白在感官上保持平衡。"
  },
  {
    "severity": "P2瑕疵",
    "category": "other",
    "description": "密码显隐图标（眼睛图标）风格过于工业化、通用化，线条过细且色温偏冷，与“酱园琥珀”温润、印章感的语言不符。",
    "suggestion": "重绘图标，使用稍粗的线条并赋予酱色或琥珀色，形态上可处理得更圆润或带有点状元素以契合品牌调性。"
  },
  {
    "severity": "P2瑕疵",
    "category": "dark-mode",
    "description": "卡片外阴影在暗色模式下完全消失，导致卡片与背景的层级感仅靠色差维持，深度感不足。",
    "suggestion": "在暗色模式下使用带有琥珀色调的微弱外发光（Ambient Glow）替代传统阴影，以强化卡片的悬浮感。"
  }
]
